def check_balanced(expr):
    stk = []
    brackets = {')':'(', '}':'{', ']':'['}
    for char in expr:
        if char in "({[":
            stk.append(char)
        elif char in ")}]":
            if not stk or stk[-1] != brackets[char]:
                return False
            stk.pop()
    return len(stk) == 0
