def update_price(item_id, new_price):
    found = False
    try:
        f1 = open('inventory.dat', 'rb')
        f2 = open('temp.dat', 'wb')
        while True:
            rec = pickle.load(f1)
            if rec[0] == item_id:
                rec[3] = new_price
                found = True
            pickle.dump(rec, f2)
    except EOFError:
        pass
    f1.close(); f2.close()
    os.remove('inventory.dat')
    os.rename('temp.dat', 'inventory.dat')
