Java Implementation:
import java.util.Scanner;
public class BinarySearchValidation {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter array size: ");
        int n = sc.nextInt();
        int[] arr = new int[n];
        System.out.println("Enter sorted elements in ascending order:");
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        boolean isSorted = true;
        for (int i = 0; i < n - 1; i++) {
            if (arr[i] > arr[i+1]) {
                isSorted = false;
                break;
            }
        }
        if (!isSorted) {
            System.out.println("Error: Array is not sorted. Binary search cannot be applied.");
            sc.close();
            return;
        }
        System.out.print("Enter search key: ");
        int key = sc.nextInt();
        int low = 0, high = n - 1, pos = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == key) {
                pos = mid;
                break;
            } else if (arr[mid] < key) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        if (pos != -1) {
            System.out.println("Element found at index: " + pos);
        } else {
            System.out.println("Element not found.");
        }
        sc.close();
    }
}

Step 1: Input float array. Step 2: Use nested loops for Bubble Sort (descending order: if arr[j] < arr[j+1], swap). Step 3: Maintain counters for passes and swaps. Step 4: Optimize by using a swapped boolean flag to break early if no swaps occur in a pass.

Java Implementation:
import java.util.Scanner;
public class BubbleSortAnalysis {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter size: ");
        int n = sc.nextInt();
        float[] arr = new float[n];
        System.out.println("Enter float elements:");
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextFloat();
        }
        int passes = 0, swaps = 0;
        for (int i = 0; i < n - 1; i++) {
            passes++;
            boolean swapped = false;
            for (int j = 0; j < n - 1 - i; j++) {
                if (arr[j] < arr[j+1]) {
                    float temp = arr[j];
                    arr[j] = arr[j+1];
                    arr[j+1] = temp;
                    swaps++;
                    swapped = true;
                }
            }
            if (!swapped) break;
        }
        System.out.println("Total Passes: " + passes);
        System.out.println("Total Swaps: " + swaps);
        System.out.println("Sorted Array (Descending):");
        for (float f : arr) {
            System.out.print(f + " ");
        }
        System.out.println();
        sc.close();
    }
}

