import java.util.Scanner;
public class KaprekarNumber {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int num = sc.nextInt();
        if (num <= 0) {
            System.out.println("Please enter a positive integer.");
            sc.close();
            return;
        }
        long square = (long) num * num;
        String sSquare = Long.toString(square);
        int len = sSquare.length();
        boolean isKaprekar = false;
        if (num == 1) {
            isKaprekar = true;
        } else {
            for (int i = 1; i < len; i++) {
                long left = Long.parseLong(sSquare.substring(0, i));
                long right = Long.parseLong(sSquare.substring(i));
                if (right > 0 && (left + right) == num) {
                    isKaprekar = true;
                    break;
                }
            }
        }
        if (isKaprekar) {
            System.out.println(num + " is a Kaprekar Number.");
        } else {
            System.out.println(num + " is not a Kaprekar Number.");
        }
        sc.close();
    }
}

Step 1: Read order N and 2D array. Step 2: Compute the sum of the primary diagonal (where row == col) as a reference sum. Step 3: Compute secondary diagonal sum (where row + col == N - 1) and verify it equals reference. Step 4: Compute sum for each row and each column, verifying equality with reference sum. Step 5: Output whether it is a magic square.

Java Implementation:
import java.util.Scanner;
public class MagicSquareAlgorithm {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter order N of square matrix: ");
        int n = sc.nextInt();
        int[][] mat = new int[n][n];
        System.out.println("Enter matrix elements:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = sc.nextInt();
            }
        }
        int refSum = 0, secSum = 0;
        for (int i = 0; i < n; i++) {
            refSum += mat[i][i];
            secSum += mat[i][n - 1 - i];
        }
        if (refSum != secSum) {
            System.out.println("Not a Magic Square.");
            sc.close();
            return;
        }
        boolean isMagic = true;
        for (int i = 0; i < n; i++) {
            int rowSum = 0, colSum = 0;
            for (int j = 0; j < n; j++) {
                rowSum += mat[i][j];
                colSum += mat[j][i];
            }
            if (rowSum != refSum || colSum != refSum) {
                isMagic = false;
                break;
            }
        }
        if (isMagic) {
            System.out.println("The matrix is a Magic Square with sum: " + refSum);
        } else {
            System.out.println("The matrix is not a Magic Square.");
        }
        sc.close();
    }
}

