Detailed Solution:
1. Accept 10 integers into an array.
2. Sort using nested loops for Bubble Sort.
3. Implement Binary Search algorithm:
   - Set low = 0, high = 9.
   - Find mid = (low + high) / 2.
   - Compare search key with array[mid]. Adjust pointers accordingly.

Sample Java Code:
import java.util.Scanner;
public class SortAndSearch {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] a = new int[10];
        System.out.println("Enter 10 integers:");
        for(int i=0; i<10; i++) a[i] = sc.nextInt();
        // Bubble Sort
        for(int i=0; i<9; i++) {
            for(int j=0; j<9-i; j++) {
                if(a[j] > a[j+1]) {
                    int t = a[j]; a[j] = a[j+1]; a[j+1] = t;
                }
            }
        }
        System.out.print("Enter element to search: ");
        int key = sc.nextInt();
        int low = 0, high = 9, pos = -1;
        while(low <= high) {
            int mid = (low + high) / 2;
            if(a[mid] == key) { pos = mid; break; }
            else if(a[mid] < key) low = mid + 1;
            else high = mid - 1;
        }
        if(pos != -1) System.out.println("Found at index: " + pos);
        else System.out.println("Not Found");
    }
}

