import java.io.*;
import java.util.Scanner;
public class WordSearch {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter word to search: ");
        String target = sc.next();
        int lineNum = 0;
        boolean found = false;
        try (BufferedReader br = new BufferedReader(new FileReader("input.txt"))) {
            String line;
            while ((line = br.readLine()) != null) {
                lineNum++;
                String[] words = line.split("\\W+");
                for (String w : words) {
                    if (w.equalsIgnoreCase(target)) {
                        System.out.println("Found on line: " + lineNum);
                        found = true;
                        break;
                    }
                }
            }
            if (!found) {
                System.out.println("Word not found in the file.");
            }
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
        sc.close();
    }
}
Rationale: Illustrates line-by-line reading, tokenizing text while handling punctuation via regex non-word splitting, and searching logic.

